import com.datastax.oss.driver.api.core.CqlSession;
import com.datastax.oss.driver.api.core.cql.BoundStatement;
import com.datastax.oss.driver.api.core.cql.PreparedStatement;
import com.datastax.oss.driver.api.core.cql.ResultSet;

public class CassandraPartitionAndTombstoneExample {

    public static void deleteUserRecord(CqlSession session, String userId) {
        // The partition key 'user_id' determines which token range on the ring owns this row.
        // Executing this delete writes a tombstone into the commitlog and memtable.
        PreparedStatement pstmt = session.prepare(
            "DELETE FROM app.users WHERE user_id = ?"
        );

        BoundStatement bound = pstmt.bind(userId);
        ResultSet rs = session.execute(bound);

        System.out.println("Tombstone successfully written for partition: " + userId);
    }
}
